import{_ as t,c as o,ae as a,o as r}from"./chunks/framework.Buicxtqr.js";const s="/assets/setup%20-%20external.DkYwv_qQ.png",n="/assets/setup%20-%20external%20add%20key.CwOPfP6c.png",l="/assets/BuddyGenAI%20-%20Local%20Model%20Setup.CgjGcujC.gif",i="/assets/setup%20-%20step%202%20with%20name.fyzBhsqI.png",u="/assets/setup%20-%20description%20magic%20button.VUxt4rdr.png",p="/assets/setup%20-%20img%20keywords%20magic%20button.Ba7dg_cK.png",d="/assets/setup%20-%20make%20pic.Dcr8m3mV.png",h="/assets/chat.DG-05YBK.png",c="/assets/sidebar%20-%20settings.DCsF1UWT.png",m="/assets/gpu%20restart%20chat.Bqe3clI5.png",v=JSON.parse('{"title":"How to setup for the first time","description":"","frontmatter":{},"headers":[],"relativePath":"how-to-setup.md","filePath":"how-to-setup.md"}'),g={name:"how-to-setup.md"};function f(y,e,k,w,b,_){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="how-to-setup-for-the-first-time" tabindex="-1">How to setup for the first time <a class="header-anchor" href="#how-to-setup-for-the-first-time" aria-label="Permalink to &quot;How to setup for the first time&quot;">​</a></h1><div class="warning custom-block github-alert"><p class="custom-block-title">This page isn&#39;t updated and is for an early version of BuddyGenAI. See [here](./getting-started.md) for current instructions and links.</p><p></p></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li>Most of the time, closing the app and opening it again will fix any issues.</li><li>Chat can take a while to start up. If the sidebar says Chat Starting for more than 30s, try restarting the app.</li></ul><p>You can use BuddyGenAI using OpenAI&#39;s models or you can bring-your-own-models and run them on your own PC.</p><p>Open the app if you haven&#39;t already. You&#39;ll see the setup screen:</p><p><img src="'+s+'" alt="BuddyGen AI setup 1"></p><p>Do you want to use <a href="#openai-models-setup">OpenAI&#39;s models</a> or <a href="#local-models-setup">run your own</a>?</p><h2 id="openai-models-setup" tabindex="-1">OpenAI Models Setup <a class="header-anchor" href="#openai-models-setup" aria-label="Permalink to &quot;OpenAI Models Setup&quot;">​</a></h2><p>First, you&#39;ll need to <a href="https://platform.openai.com/signup" target="_blank" rel="noreferrer">Sign Up</a> or <a href="https://platform.openai.com/login" target="_blank" rel="noreferrer">Log In</a> to your OpenAI account.</p><p>Now go to the <a href="https://platform.openai.com/account/api-keys" target="_blank" rel="noreferrer">API Keys</a> page and click &quot;Create new secret key&quot;. Give it a name if you want to and click &quot;Create secret key&quot;. Now click Copy</p><p><img src="'+n+'" alt="BuddyGen AI setup 2"></p><h2 id="local-models-setup" tabindex="-1">Local Models Setup <a class="header-anchor" href="#local-models-setup" aria-label="Permalink to &quot;Local Models Setup&quot;">​</a></h2><p>(<strong>Experimental</strong>) -- This feature is still in active development. If you run into any issues or have suggestions to improve anything, please <a href="https://github.com/parsehex/BuddyGenAI/issues" target="_blank" rel="noreferrer">create a new issue</a>.</p><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><p>You should download and install the following before continuing:</p><ul><li><a href="https://aka.ms/vs/17/release/vc_redist.x64.exe" target="_blank" rel="noreferrer">Microsoft Visual C++ Redistributable x64</a></li><li>(if you have NVIDIA GPU) <a href="https://developer.nvidia.com/cuda-downloads" target="_blank" rel="noreferrer">CUDA Toolkit</a></li><li>(if you have AMD GPU) <a href="https://www.amd.com/en/developer/resources/rocm-hub/hip-sdk.html" target="_blank" rel="noreferrer">ROCm SDK</a> -- not tested yet</li></ul><h3 id="download-ai-models" tabindex="-1">Download AI Models <a class="header-anchor" href="#download-ai-models" aria-label="Permalink to &quot;Download AI Models&quot;">​</a></h3><p>You&#39;ll also need to download some AI models if you don&#39;t already have them - a chat model like Llama 3 and a Stable Diffusion (1.5) model.</p><p>The following are the models that I&#39;ve mainly used while making the app. Support for more models will be added in the future.</p><p>The following are the models that I&#39;ve been using while making the app (other may work as well), I&#39;ve included links to download them from Hugging Face and Civitai for convenience.</p><p>Depending on how powerful your PC is, you can choose a model with a higher number (e.g. &gt;=Q4_K) and you&#39;ll get better results. I don&#39;t have a good way to pick a good size at the moment, feel free to <a href="https://github.com/parsehex/BuddyGenAI/discussions" target="_blank" rel="noreferrer">reach out</a> if you need help.</p><p>You&#39;ll need to download a chat model (e.g. 1 of the Llama 3 links below) and an SD 1.5 image model (e.g. Toonify SD 1.5 below).</p><ul><li>Llama 3 <ul><li>Q2_K - This is a good one to start with <ul><li>Download <a href="https://huggingface.co/bartowski/Meta-Llama-3-8B-Instruct-GGUF/resolve/main/Meta-Llama-3-8B-Instruct-Q2_K.gguf" target="_blank" rel="noreferrer">Here</a> or <a href="https://huggingface.co/QuantFactory/Meta-Llama-3-8B-Instruct-GGUF/resolve/main/Meta-Llama-3-8B-Instruct.Q2_K.gguf" target="_blank" rel="noreferrer">Here</a></li></ul></li><li>Q4_K <ul><li>Download <a href="https://huggingface.co/bartowski/Meta-Llama-3-8B-Instruct-GGUF/resolve/main/Meta-Llama-3-8B-Instruct-Q4_K.gguf" target="_blank" rel="noreferrer">Here</a> or <a href="https://huggingface.co/QuantFactory/Meta-Llama-3-8B-Instruct-GGUF/resolve/main/Meta-Llama-3-8B-Instruct.Q4_K.gguf" target="_blank" rel="noreferrer">Here</a> or <a href="https://huggingface.co/QuantFactory/Meta-Llama-3-8B-Instruct-GGUF/resolve/main/Meta-Llama-3-8B-Instruct.Q4_K.gguf" target="_blank" rel="noreferrer">Here</a></li></ul></li></ul></li><li>Toonify SD 1.5 - <a href="https://civitai.com/api/download/models/244831" target="_blank" rel="noreferrer">Download Here</a></li></ul><h3 id="move-models-finish-setup" tabindex="-1">Move Models &amp; Finish Setup <a class="header-anchor" href="#move-models-finish-setup" aria-label="Permalink to &quot;Move Models &amp; Finish Setup&quot;">​</a></h3><p>Now that you have the models downloaded, you&#39;ll need to move them to the correct location.</p><p>Open BuddyGenAI and click &quot;Local Models&quot; on the setup screen, then follow this gif:</p><p><img src="'+l+'" alt="BuddyGen AI setup 1"></p><ul><li>Click on Open Folder</li><li>Go to Downloads (or wherever you saved the models)</li><li>Select and right-click the model files you downloaded and click Cut (or Copy)</li><li>Click the Back button to go back to the <code>Models</code> folder</li><li>Right-click in the folder and click Paste</li><li>Close the folder and click &quot;Update Models&quot; in the app</li><li>Select the Chat Model and then the Image Model</li></ul><hr><p>Now you&#39;re ready to fill in your name and create your first Buddy:</p><p><img src="'+i+'" alt="BuddyGen AI setup 3"></p><p>Fill in a description you like, or click the purple Magic button to use AI to generate suggestions for your Buddy:</p><blockquote><p>Note: Magic buttons are not very fleshed out yet.</p></blockquote><p><img src="'+u+'" alt="BuddyGen AI setup 4"></p><p>Click <code>Create Buddy</code> when you&#39;re satisfied.</p><hr><p>Now you can describe your Buddy&#39;s appearance.</p><p>There&#39;s a Magic button to generate suggestions for your Buddy&#39;s appearance as well:</p><p><img src="'+p+'" alt="BuddyGen AI setup 6"></p><p>Click &quot;Accept &amp; Make Picture&quot; and wait for the picture to be generated. You can click &quot;Make Profile Picture&quot; until you find one you like and then click &quot;Save&quot;:</p><p><img src="'+d+'" alt="BuddyGen AI setup 7"></p><p>Start talking with your Buddy:</p><p><img src="'+h+'" alt="BuddyGen AI setup 8"></p><hr><p><strong>Using a GPU?</strong></p><p>If you&#39;ve followed the instructions so far then you&#39;ll need to do one more thing for the chat model to take advantage of your hardware.</p><p>Assuming you chose one of the Llama 3 models above, then go to the Settings tab:</p><p><img src="'+c+'" alt="BuddyGen AI settings"></p><p>Change &quot;Number of GPU Layers&quot; to 35.</p><p>Now either restart the app or go to the Chat tab, click on the (green) &quot;Chat Online&quot; to restart the chat manually:</p><p><img src="'+m+'" alt="BuddyGen AI chat server"></p>',52)]))}const q=t(g,[["render",f]]);export{v as __pageData,q as default};
